import { SAMPLE_RATE } from "../core/constants.js";
import { DictationStreamConnection } from "./dictation-stream-connection.js";
import { StreamSession } from "./dictation-stream-session.js";
export const DEFAULT_STREAM_LINGER_MS = 60_000;
export const DEFAULT_STREAM_CONNECT_TIMEOUT_MS = 10_000;
export const DEFAULT_STREAM_STOP_TIMEOUT_MS = 45_000;
export const DEFAULT_STREAM_MAX_QUEUED_AUDIO_MS = 30_000;
export function createDictationStreamClient(options) {
  return new StreamClient(options);
}
class StreamClient {
  options;
  lingerMs;
  maxQueuedSamples;
  connection;
  session;
  lingerTimer;
  constructor(options) {
    this.options = options;
    this.lingerMs = options.lingerMs ?? DEFAULT_STREAM_LINGER_MS;
    const maxQueuedAudioMs =
      options.maxQueuedAudioMs ?? DEFAULT_STREAM_MAX_QUEUED_AUDIO_MS;
    this.maxQueuedSamples = Math.round((maxQueuedAudioMs / 1000) * SAMPLE_RATE);
  }
  warm() {
    this.ensureConnection();
    // A socket warmed for a dictation that never starts still closes after the linger window.
    if (!this.session) this.scheduleLinger();
  }
  startDictation(options = {}) {
    this.session?.cancel();
    clearTimeout(this.lingerTimer);
    const connection = this.ensureConnection();
    this.session = new StreamSession({
      connection,
      token: this.options.getToken(),
      start: options,
      maxQueuedSamples: this.maxQueuedSamples,
      stopTimeoutMs:
        this.options.stopTimeoutMs ?? DEFAULT_STREAM_STOP_TIMEOUT_MS,
      onSettled: (reusable) => this.handleSessionSettled(reusable),
    });
    return this.session;
  }
  close() {
    this.session?.cancel();
    this.closeConnection();
  }
  ensureConnection() {
    if (this.connection) return this.connection;
    this.connection = new DictationStreamConnection({
      url: this.options.url,
      WebSocket: this.options.WebSocket ?? globalThis.WebSocket,
      connectTimeoutMs:
        this.options.connectTimeoutMs ?? DEFAULT_STREAM_CONNECT_TIMEOUT_MS,
      onMessage: (message) => this.session?.handleMessage(message),
      onClose: (error) => this.handleConnectionClosed(error),
    });
    return this.connection;
  }
  handleSessionSettled(reusable) {
    this.session = undefined;
    if (!reusable) {
      this.closeConnection();
      return;
    }
    this.scheduleLinger();
  }
  handleConnectionClosed(error) {
    this.connection = undefined;
    clearTimeout(this.lingerTimer);
    this.session?.handleClose(error);
  }
  scheduleLinger() {
    clearTimeout(this.lingerTimer);
    this.lingerTimer = setTimeout(() => this.closeConnection(), this.lingerMs);
  }
  closeConnection() {
    clearTimeout(this.lingerTimer);
    this.connection?.close();
    this.connection = undefined;
  }
}
